  CONSTRAINT `ck_due_promise_1` CHECK (`is_backfilled` IN (0,1))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='Persists the promised-by date (R9.1/R9.3). Latest wins.';

CREATE TABLE `clinical_order_status` (
  `clinical_order_status_id` BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
  `clinical_order_id` BIGINT UNSIGNED NOT NULL,
  `status` VARCHAR(13) NOT NULL,
  `reason` VARCHAR(300) NULL DEFAULT NULL,
  `occurred_at` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  `recorded_at` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  `recorded_by` BIGINT UNSIGNED NOT NULL DEFAULT 0,
  `recorded_by_role` VARCHAR(20) NOT NULL DEFAULT '',
  `is_backfilled` TINYINT(1) NOT NULL DEFAULT 0,
  `request_uuid` CHAR(36) NOT NULL DEFAULT (UUID()),
  PRIMARY KEY (`clinical_order_status_id`),
  UNIQUE KEY `uq_clinical_order_status_request_uuid` (`request_uuid`),
  CONSTRAINT `fk_clinical_order_status_clinical_order` FOREIGN KEY (`clinical_order_id`) REFERENCES `clinical_order` (`clinical_order_id`),
  CONSTRAINT `fk_clinical_order_status_staff` FOREIGN KEY (`recorded_by`) REFERENCES `staff` (`staff_id`),
  CONSTRAINT `fk_clinical_order_status_role` FOREIGN KEY (`recorded_by_role`) REFERENCES `role` (`role_code`),
  CONSTRAINT `ck_clinical_order_status_1` CHECK (`status` IN ('ordered','finalized','cancelled','completed')),
  CONSTRAINT `ck_clinical_order_status_2` CHECK (`is_backfilled` IN (0,1))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='Order lifecycle; nurses see finalized orders.';

CREATE TABLE `discharge` (
  `discharge_id` BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
  `visit_id` BIGINT UNSIGNED NOT NULL,
  `clinical_signoff_id` BIGINT UNSIGNED NOT NULL,
  `financial_gate_basis` VARCHAR(28) NOT NULL,
  `approval_request_id` BIGINT UNSIGNED NULL DEFAULT NULL,
  `clinical_emergency_override_id` BIGINT UNSIGNED NULL DEFAULT NULL,
  `occurred_at` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  `recorded_at` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  `recorded_by` BIGINT UNSIGNED NOT NULL DEFAULT 0,
  `recorded_by_role` VARCHAR(20) NOT NULL DEFAULT '',
  `is_backfilled` TINYINT(1) NOT NULL DEFAULT 0,
  `request_uuid` CHAR(36) NOT NULL DEFAULT (UUID()),
  PRIMARY KEY (`discharge_id`),
  UNIQUE KEY `uq_discharge_1` (`visit_id`),
  UNIQUE KEY `uq_discharge_2` (`clinical_emergency_override_id`),
  UNIQUE KEY `uq_discharge_3` (`approval_request_id`),
  UNIQUE KEY `uq_discharge_request_uuid` (`request_uuid`),
  CONSTRAINT `fk_discharge_visit` FOREIGN KEY (`visit_id`) REFERENCES `visit` (`visit_id`),
  CONSTRAINT `fk_discharge_clinical_signoff` FOREIGN KEY (`clinical_signoff_id`) REFERENCES `clinical_signoff` (`clinical_signoff_id`),
  CONSTRAINT `fk_discharge_approval_request` FOREIGN KEY (`approval_request_id`) REFERENCES `approval_request` (`approval_request_id`),
  CONSTRAINT `fk_discharge_clinical_emergency_override` FOREIGN KEY (`clinical_emergency_override_id`) REFERENCES `clinical_emergency_override` (`clinical_emergency_override_id`),
  CONSTRAINT `fk_discharge_staff` FOREIGN KEY (`recorded_by`) REFERENCES `staff` (`staff_id`),
  CONSTRAINT `fk_discharge_role` FOREIGN KEY (`recorded_by_role`) REFERENCES `role` (`role_code`),
  CONSTRAINT `ck_discharge_1` CHECK (`financial_gate_basis` IN ('bill_settled','approved_partial_payment','emergency_override')),
  CONSTRAINT `ck_discharge_2` CHECK (`is_backfilled` IN (0,1)),
  CONSTRAINT `ck_discharge_3` CHECK ((financial_gate_basis = 'approved_partial_payment') = (approval_request_id IS NOT NULL)),
  CONSTRAINT `ck_discharge_4` CHECK ((financial_gate_basis = 'emergency_override') = (clinical_emergency_override_id IS NOT NULL))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='One transaction closes visit, stay and bill (R9.4).';

CREATE TABLE `prescription_item` (
  `prescription_item_id` BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
  `prescription_version_id` BIGINT UNSIGNED NOT NULL,
  `prescription_line_id` BIGINT UNSIGNED NOT NULL,
  `prescription_id` BIGINT UNSIGNED NOT NULL,
  `item_change` VARCHAR(16) NOT NULL,
  `medicine_id` BIGINT UNSIGNED NULL DEFAULT NULL,
  `free_text_medicine_name` VARCHAR(150) NULL DEFAULT NULL,
  `chosen_dose_text` VARCHAR(60) NULL DEFAULT NULL,
  `chosen_schedule` VARCHAR(30) NULL DEFAULT NULL,
  `food_instruction` VARCHAR(60) NULL DEFAULT NULL,
  `duration_days` SMALLINT NULL DEFAULT NULL,
  `quantity_prescribed` DECIMAL(10,2) NULL DEFAULT NULL,
  `occurred_at` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  `recorded_at` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  `recorded_by` BIGINT UNSIGNED NOT NULL DEFAULT 0,
  `recorded_by_role` VARCHAR(20) NOT NULL DEFAULT '',
  `is_backfilled` TINYINT(1) NOT NULL DEFAULT 0,
  `request_uuid` CHAR(36) NOT NULL DEFAULT (UUID()),
  PRIMARY KEY (`prescription_item_id`),
  UNIQUE KEY `uq_prescription_item_1` (`prescription_version_id`, `prescription_line_id`),
  UNIQUE KEY `uq_prescription_item_request_uuid` (`request_uuid`),
  CONSTRAINT `fk_prescription_item_medicine` FOREIGN KEY (`medicine_id`) REFERENCES `medicine` (`medicine_id`),
  CONSTRAINT `fk_prescription_item_staff` FOREIGN KEY (`recorded_by`) REFERENCES `staff` (`staff_id`),
  CONSTRAINT `fk_prescription_item_role` FOREIGN KEY (`recorded_by_role`) REFERENCES `role` (`role_code`),
  CONSTRAINT `fk_prescription_item_prescription_version_c` FOREIGN KEY (`prescription_version_id`, `prescription_id`) REFERENCES `prescription_version` (`prescription_version_id`, `prescription_id`),
  CONSTRAINT `fk_prescription_item_prescription_line_c` FOREIGN KEY (`prescription_line_id`, `prescription_id`) REFERENCES `prescription_line` (`prescription_line_id`, `prescription_id`),
  CONSTRAINT `ck_prescription_item_1` CHECK (`item_change` IN ('added','modified','unchanged','discontinued')),
  CONSTRAINT `ck_prescription_item_2` CHECK (`is_backfilled` IN (0,1)),
  CONSTRAINT `ck_prescription_item_3` CHECK ((medicine_id IS NULL) <> (free_text_medicine_name IS NULL))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='Version x Line. Stores what the doctor chose (R4.3).';

CREATE TABLE `lab_order` (
  `lab_order_id` BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
  `visit_id` BIGINT UNSIGNED NOT NULL,
  `outside_lab_id` BIGINT UNSIGNED NOT NULL,
  `clinical_order_id` BIGINT UNSIGNED NULL DEFAULT NULL,
  `test_name` VARCHAR(150) NOT NULL,
  `occurred_at` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  `recorded_at` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  `recorded_by` BIGINT UNSIGNED NOT NULL DEFAULT 0,
  `recorded_by_role` VARCHAR(20) NOT NULL DEFAULT '',
  `is_backfilled` TINYINT(1) NOT NULL DEFAULT 0,
  `request_uuid` CHAR(36) NOT NULL DEFAULT (UUID()),
  PRIMARY KEY (`lab_order_id`),
  UNIQUE KEY `uq_lab_order_request_uuid` (`request_uuid`),
  CONSTRAINT `fk_lab_order_visit` FOREIGN KEY (`visit_id`) REFERENCES `visit` (`visit_id`),
  CONSTRAINT `fk_lab_order_outside_lab` FOREIGN KEY (`outside_lab_id`) REFERENCES `outside_lab` (`outside_lab_id`),
  CONSTRAINT `fk_lab_order_clinical_order` FOREIGN KEY (`clinical_order_id`) REFERENCES `clinical_order` (`clinical_order_id`),
  CONSTRAINT `fk_lab_order_staff` FOREIGN KEY (`recorded_by`) REFERENCES `staff` (`staff_id`),
  CONSTRAINT `fk_lab_order_role` FOREIGN KEY (`recorded_by_role`) REFERENCES `role` (`role_code`),
  CONSTRAINT `ck_lab_order_1` CHECK (`is_backfilled` IN (0,1))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='Doctor-authored lab order. Billing/status live elsewhere.';

CREATE TABLE `clinical_order_item` (
  `clinical_order_item_id` BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
  `clinical_order_id` BIGINT UNSIGNED NOT NULL,
  `item_no` SMALLINT NOT NULL,
  `item_kind` VARCHAR(15) NOT NULL,
  `medicine_id` BIGINT UNSIGNED NULL DEFAULT NULL,
  `free_text_medicine_name` VARCHAR(150) NULL DEFAULT NULL,
  `price_list_id` BIGINT UNSIGNED NULL DEFAULT NULL,
  `dose_value` DECIMAL(10,3) NULL DEFAULT NULL,
  `dose_unit` VARCHAR(20) NULL DEFAULT NULL,
  `route` VARCHAR(30) NULL DEFAULT NULL,
  `first_scheduled_at` DATETIME(3) NULL DEFAULT NULL,
  `repeat_interval_minutes` INT NULL DEFAULT NULL,
  `quantity_ordered` DECIMAL(10,2) NULL DEFAULT NULL,
  `instructions` VARCHAR(300) NULL DEFAULT NULL,
  `supersedes_clinical_order_item_id` BIGINT UNSIGNED NULL DEFAULT NULL,
  `occurred_at` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  `recorded_at` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  `recorded_by` BIGINT UNSIGNED NOT NULL DEFAULT 0,
  `recorded_by_role` VARCHAR(20) NOT NULL DEFAULT '',
  `is_backfilled` TINYINT(1) NOT NULL DEFAULT 0,
  `request_uuid` CHAR(36) NOT NULL DEFAULT (UUID()),
  PRIMARY KEY (`clinical_order_item_id`),
  UNIQUE KEY `uq_clinical_order_item_1` (`clinical_order_id`, `item_no`),
  UNIQUE KEY `uq_clinical_order_item_request_uuid` (`request_uuid`),
  CONSTRAINT `fk_clinical_order_item_clinical_order` FOREIGN KEY (`clinical_order_id`) REFERENCES `clinical_order` (`clinical_order_id`),
  CONSTRAINT `fk_clinical_order_item_medicine` FOREIGN KEY (`medicine_id`) REFERENCES `medicine` (`medicine_id`),
  CONSTRAINT `fk_clinical_order_item_price_list` FOREIGN KEY (`price_list_id`) REFERENCES `price_list` (`price_list_id`),
  CONSTRAINT `fk_clinical_order_item_clinical_order_item` FOREIGN KEY (`supersedes_clinical_order_item_id`) REFERENCES `clinical_order_item` (`clinical_order_item_id`),
  CONSTRAINT `fk_clinical_order_item_staff` FOREIGN KEY (`recorded_by`) REFERENCES `staff` (`staff_id`),
  CONSTRAINT `fk_clinical_order_item_role` FOREIGN KEY (`recorded_by_role`) REFERENCES `role` (`role_code`),
  CONSTRAINT `ck_clinical_order_item_1` CHECK (`item_kind` IN ('medication','procedure','observation')),
  CONSTRAINT `ck_clinical_order_item_2` CHECK (`is_backfilled` IN (0,1))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='Weak on order; a change is a new item superseding the old.';

CREATE TABLE `catalog_review_queue` (
  `catalog_review_queue_id` BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
  `prescription_item_id` BIGINT UNSIGNED NOT NULL,
  `submitted_name` VARCHAR(150) NOT NULL,
  `occurred_at` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  `recorded_at` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  `recorded_by` BIGINT UNSIGNED NOT NULL DEFAULT 0,
  `recorded_by_role` VARCHAR(20) NOT NULL DEFAULT '',
  `is_backfilled` TINYINT(1) NOT NULL DEFAULT 0,
  `request_uuid` CHAR(36) NOT NULL DEFAULT (UUID()),
  PRIMARY KEY (`catalog_review_queue_id`),
  UNIQUE KEY `uq_catalog_review_queue_1` (`prescription_item_id`),
  UNIQUE KEY `uq_catalog_review_queue_request_uuid` (`request_uuid`),
  CONSTRAINT `fk_catalog_review_queue_prescription_item` FOREIGN KEY (`prescription_item_id`) REFERENCES `prescription_item` (`prescription_item_id`),
  CONSTRAINT `fk_catalog_review_queue_staff` FOREIGN KEY (`recorded_by`) REFERENCES `staff` (`staff_id`),
  CONSTRAINT `fk_catalog_review_queue_role` FOREIGN KEY (`recorded_by_role`) REFERENCES `role` (`role_code`),
  CONSTRAINT `ck_catalog_review_queue_1` CHECK (`is_backfilled` IN (0,1))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='Free-text medicine names awaiting mapping (R4.5).';

CREATE TABLE `lab_report` (
  `lab_report_id` BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
  `lab_order_id` BIGINT UNSIGNED NOT NULL,
  `version_number` SMALLINT NOT NULL,
  `supersedes_lab_report_id` BIGINT UNSIGNED NULL DEFAULT NULL,
  `file_path` VARCHAR(300) NOT NULL,
  `content_hash` CHAR(64) NOT NULL,
  `source` VARCHAR(22) NOT NULL,
  `occurred_at` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  `recorded_at` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  `recorded_by` BIGINT UNSIGNED NOT NULL DEFAULT 0,
  `recorded_by_role` VARCHAR(20) NOT NULL DEFAULT '',
  `is_backfilled` TINYINT(1) NOT NULL DEFAULT 0,
  `request_uuid` CHAR(36) NOT NULL DEFAULT (UUID()),
  PRIMARY KEY (`lab_report_id`),
  UNIQUE KEY `uq_lab_report_1` (`lab_order_id`, `version_number`),
  UNIQUE KEY `uq_lab_report_request_uuid` (`request_uuid`),
  CONSTRAINT `fk_lab_report_lab_order` FOREIGN KEY (`lab_order_id`) REFERENCES `lab_order` (`lab_order_id`),
  CONSTRAINT `fk_lab_report_lab_report` FOREIGN KEY (`supersedes_lab_report_id`) REFERENCES `lab_report` (`lab_report_id`),
  CONSTRAINT `fk_lab_report_staff` FOREIGN KEY (`recorded_by`) REFERENCES `staff` (`staff_id`),
  CONSTRAINT `fk_lab_report_role` FOREIGN KEY (`recorded_by_role`) REFERENCES `role` (`role_code`),
  CONSTRAINT `ck_lab_report_1` CHECK (`source` IN ('from_lab','brought_by_patient')),
  CONSTRAINT `ck_lab_report_2` CHECK (`is_backfilled` IN (0,1)),
  CONSTRAINT `ck_lab_report_3` CHECK (content_hash REGEXP '^[0-9a-f]{64}$')
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='Report stored as received with hash; correction = new version (R7.3).';

CREATE TABLE `lab_report_identifier_check` (
  `lab_report_identifier_check_id` BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
  `lab_report_id` BIGINT UNSIGNED NOT NULL,
  `identifier_kind` VARCHAR(17) NOT NULL,
  `value_seen` VARCHAR(120) NOT NULL,
  `matches_order` TINYINT(1) NOT NULL,
  `occurred_at` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  `recorded_at` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  `recorded_by` BIGINT UNSIGNED NOT NULL DEFAULT 0,
  `recorded_by_role` VARCHAR(20) NOT NULL DEFAULT '',
  `is_backfilled` TINYINT(1) NOT NULL DEFAULT 0,
  `request_uuid` CHAR(36) NOT NULL DEFAULT (UUID()),
  PRIMARY KEY (`lab_report_identifier_check_id`),
  UNIQUE KEY `uq_lab_report_identifier_check_request_uuid` (`request_uuid`),
  CONSTRAINT `fk_lab_report_identifier_check_lab_report` FOREIGN KEY (`lab_report_id`) REFERENCES `lab_report` (`lab_report_id`),
  CONSTRAINT `fk_lab_report_identifier_check_staff` FOREIGN KEY (`recorded_by`) REFERENCES `staff` (`staff_id`),
  CONSTRAINT `fk_lab_report_identifier_check_role` FOREIGN KEY (`recorded_by_role`) REFERENCES `role` (`role_code`),
  CONSTRAINT `ck_lab_report_identifier_check_1` CHECK (`identifier_kind` IN ('patient_name','date_of_birth','patient_code','phone_last4','age_gender')),
  CONSTRAINT `ck_lab_report_identifier_check_2` CHECK (`matches_order` IN (0,1)),
  CONSTRAINT `ck_lab_report_identifier_check_3` CHECK (`is_backfilled` IN (0,1))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='Identifiers confirmed against the order (>= 2 distinct kinds).';

CREATE TABLE `clinical_order_item_status` (
  `clinical_order_item_status_id` BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
  `clinical_order_item_id` BIGINT UNSIGNED NOT NULL,
  `status` VARCHAR(14) NOT NULL,
  `reason` VARCHAR(300) NULL DEFAULT NULL,
  `occurred_at` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  `recorded_at` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  `recorded_by` BIGINT UNSIGNED NOT NULL DEFAULT 0,
  `recorded_by_role` VARCHAR(20) NOT NULL DEFAULT '',
  `is_backfilled` TINYINT(1) NOT NULL DEFAULT 0,
  `request_uuid` CHAR(36) NOT NULL DEFAULT (UUID()),
  PRIMARY KEY (`clinical_order_item_status_id`),
  UNIQUE KEY `uq_clinical_order_item_status_request_uuid` (`request_uuid`),
  CONSTRAINT `fk_clinical_order_item_status_clinical_order_item` FOREIGN KEY (`clinical_order_item_id`) REFERENCES `clinical_order_item` (`clinical_order_item_id`),
  CONSTRAINT `fk_clinical_order_item_status_staff` FOREIGN KEY (`recorded_by`) REFERENCES `staff` (`staff_id`),
  CONSTRAINT `fk_clinical_order_item_status_role` FOREIGN KEY (`recorded_by_role`) REFERENCES `role` (`role_code`),
  CONSTRAINT `ck_clinical_order_item_status_1` CHECK (`status` IN ('active','stopped','superseded')),
  CONSTRAINT `ck_clinical_order_item_status_2` CHECK (`is_backfilled` IN (0,1))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='Item stop/change by the doctor. Latest = current.';

CREATE TABLE `lab_order_status` (
  `lab_order_status_id` BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
  `lab_order_id` BIGINT UNSIGNED NOT NULL,
  `status` VARCHAR(20) NOT NULL,
  `reason` VARCHAR(300) NULL DEFAULT NULL,
  `occurred_at` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  `recorded_at` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  `recorded_by` BIGINT UNSIGNED NOT NULL DEFAULT 0,
  `recorded_by_role` VARCHAR(20) NOT NULL DEFAULT '',
  `is_backfilled` TINYINT(1) NOT NULL DEFAULT 0,
  `request_uuid` CHAR(36) NOT NULL DEFAULT (UUID()),
  PRIMARY KEY (`lab_order_status_id`),
  UNIQUE KEY `uq_lab_order_status_request_uuid` (`request_uuid`),
  CONSTRAINT `fk_lab_order_status_lab_order` FOREIGN KEY (`lab_order_id`) REFERENCES `lab_order` (`lab_order_id`),
  CONSTRAINT `fk_lab_order_status_staff` FOREIGN KEY (`recorded_by`) REFERENCES `staff` (`staff_id`),
  CONSTRAINT `fk_lab_order_status_role` FOREIGN KEY (`recorded_by_role`) REFERENCES `role` (`role_code`),
  CONSTRAINT `ck_lab_order_status_1` CHECK (`status` IN ('ordered','sample_collected','sent_to_lab','cancelled')),
  CONSTRAINT `ck_lab_order_status_2` CHECK (`is_backfilled` IN (0,1))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='Order lifecycle steps only; report/review facts live on their own tables.';

CREATE TABLE `lab_order_price` (
  `lab_order_price_id` BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
  `lab_order_id` BIGINT UNSIGNED NOT NULL,
  `entered_price` DECIMAL(12,2) NOT NULL,
  `price_basis` VARCHAR(18) NOT NULL,
  `expected_price` DECIMAL(12,2) NULL DEFAULT NULL,
  `is_price_deviation` TINYINT(1) NOT NULL DEFAULT 0,
  `deviation_reason` VARCHAR(300) NULL DEFAULT NULL,
  `occurred_at` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  `recorded_at` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  `recorded_by` BIGINT UNSIGNED NOT NULL DEFAULT 0,
  `recorded_by_role` VARCHAR(20) NOT NULL DEFAULT '',
  `is_backfilled` TINYINT(1) NOT NULL DEFAULT 0,
  `request_uuid` CHAR(36) NOT NULL DEFAULT (UUID()),
  `corrects_id` BIGINT UNSIGNED NULL DEFAULT NULL,
  PRIMARY KEY (`lab_order_price_id`),
  UNIQUE KEY `uq_lab_order_price_request_uuid` (`request_uuid`),
  CONSTRAINT `fk_lab_order_price_lab_order` FOREIGN KEY (`lab_order_id`) REFERENCES `lab_order` (`lab_order_id`),
  CONSTRAINT `fk_lab_order_price_staff` FOREIGN KEY (`recorded_by`) REFERENCES `staff` (`staff_id`),
  CONSTRAINT `fk_lab_order_price_role` FOREIGN KEY (`recorded_by_role`) REFERENCES `role` (`role_code`),
  CONSTRAINT `fk_lab_order_price_lab_order_price` FOREIGN KEY (`corrects_id`) REFERENCES `lab_order_price` (`lab_order_price_id`),
  CONSTRAINT `ck_lab_order_price_1` CHECK (`price_basis` IN ('price_list','previous_price','manual')),
  CONSTRAINT `ck_lab_order_price_2` CHECK (`is_price_deviation` IN (0,1)),
  CONSTRAINT `ck_lab_order_price_3` CHECK (`is_backfilled` IN (0,1)),
  CONSTRAINT `ck_lab_order_price_4` CHECK (entered_price >= 0),
  CONSTRAINT `ck_lab_order_price_5` CHECK (is_price_deviation = 0 OR deviation_reason IS NOT NULL)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='Per-test price with deviation flag (R8.1).';

CREATE TABLE `bill_line` (
  `bill_line_id` BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
  `bill_id` BIGINT UNSIGNED NOT NULL,
  `line_no` SMALLINT NOT NULL,
  `line_type` VARCHAR(28) NOT NULL,
  `price_list_id` BIGINT UNSIGNED NULL DEFAULT NULL,
  `source_stock_movement_id` BIGINT UNSIGNED NULL DEFAULT NULL,
  `lab_order_id` BIGINT UNSIGNED NULL DEFAULT NULL,
  `short_stay_episode_id` BIGINT UNSIGNED NULL DEFAULT NULL,
  `description_snapshot` VARCHAR(200) NOT NULL,
  `quantity` DECIMAL(10,2) NOT NULL,
  `unit_price_snapshot` DECIMAL(12,2) NOT NULL,
  `price_source` VARCHAR(15) NOT NULL,
  `is_manual_price` TINYINT(1) NOT NULL DEFAULT 0,
  `expected_unit_price` DECIMAL(12,2) NULL DEFAULT NULL,
  `is_price_deviation` TINYINT(1) NOT NULL DEFAULT 0,
  `reason` VARCHAR(300) NULL DEFAULT NULL,
  `reverses_bill_line_id` BIGINT UNSIGNED NULL DEFAULT NULL,
  `approval_request_id` BIGINT UNSIGNED NULL DEFAULT NULL,
  `occurred_at` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  `recorded_at` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  `recorded_by` BIGINT UNSIGNED NOT NULL DEFAULT 0,
  `recorded_by_role` VARCHAR(20) NOT NULL DEFAULT '',
  `is_backfilled` TINYINT(1) NOT NULL DEFAULT 0,
  `request_uuid` CHAR(36) NOT NULL DEFAULT (UUID()),
  line_amount DECIMAL(14,2) GENERATED ALWAYS AS (ROUND(quantity * unit_price_snapshot, 2)) STORED,
  PRIMARY KEY (`bill_line_id`),
  UNIQUE KEY `uq_bill_line_1` (`bill_id`, `line_no`),
  UNIQUE KEY `uq_bill_line_2` (`source_stock_movement_id`),
  UNIQUE KEY `uq_bill_line_3` (`approval_request_id`),
  UNIQUE KEY `uq_bill_line_request_uuid` (`request_uuid`),
  KEY `ix_bill_line_1` (`lab_order_id`),
  CONSTRAINT `fk_bill_line_bill` FOREIGN KEY (`bill_id`) REFERENCES `bill` (`bill_id`),
  CONSTRAINT `fk_bill_line_price_list` FOREIGN KEY (`price_list_id`) REFERENCES `price_list` (`price_list_id`),
  CONSTRAINT `fk_bill_line_stock_movement` FOREIGN KEY (`source_stock_movement_id`) REFERENCES `stock_movement` (`stock_movement_id`),
  CONSTRAINT `fk_bill_line_lab_order` FOREIGN KEY (`lab_order_id`) REFERENCES `lab_order` (`lab_order_id`),
  CONSTRAINT `fk_bill_line_short_stay_episode` FOREIGN KEY (`short_stay_episode_id`) REFERENCES `short_stay_episode` (`short_stay_episode_id`),
  CONSTRAINT `fk_bill_line_bill_line` FOREIGN KEY (`reverses_bill_line_id`) REFERENCES `bill_line` (`bill_line_id`),
  CONSTRAINT `fk_bill_line_approval_request` FOREIGN KEY (`approval_request_id`) REFERENCES `approval_request` (`approval_request_id`),
  CONSTRAINT `fk_bill_line_staff` FOREIGN KEY (`recorded_by`) REFERENCES `staff` (`staff_id`),
  CONSTRAINT `fk_bill_line_role` FOREIGN KEY (`recorded_by_role`) REFERENCES `role` (`role_code`),
  CONSTRAINT `ck_bill_line_1` CHECK (`line_type` IN ('price_list_item','medicine','lab_test','stay','discount','free_service','return_credit','post_finalization_credit','post_finalization_debit','manual')),
  CONSTRAINT `ck_bill_line_2` CHECK (`price_source` IN ('price_list','batch_mrp','lab_entered','manual')),
  CONSTRAINT `ck_bill_line_3` CHECK (`is_manual_price` IN (0,1)),
  CONSTRAINT `ck_bill_line_4` CHECK (`is_price_deviation` IN (0,1)),
  CONSTRAINT `ck_bill_line_5` CHECK (`is_backfilled` IN (0,1)),
  CONSTRAINT `ck_bill_line_6` CHECK (quantity > 0),
  CONSTRAINT `ck_bill_line_7` CHECK (is_manual_price = 0 OR (reason IS NOT NULL AND CHAR_LENGTH(TRIM(reason)) >= 3)),
  CONSTRAINT `ck_bill_line_8` CHECK ((line_type IN ('discount','free_service','return_credit','post_finalization_credit') AND unit_price_snapshot <= 0) OR (line_type NOT IN ('discount','free_service','return_credit','post_finalization_credit') AND unit_price_snapshot >= 0)),
  CONSTRAINT `ck_bill_line_9` CHECK (line_type NOT IN ('discount','free_service','post_finalization_credit','post_finalization_debit') OR approval_request_id IS NOT NULL)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='Weak on bill. Price snapshot; generated from events (R8.2). line_amount is a generated column.';

CREATE TABLE `lab_report_retraction` (
  `lab_report_retraction_id` BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
  `lab_report_id` BIGINT UNSIGNED NOT NULL,
  `retraction_kind` VARCHAR(21) NOT NULL,
  `correct_lab_order_id` BIGINT UNSIGNED NULL DEFAULT NULL,
  `note` VARCHAR(300) NULL DEFAULT NULL,
  `occurred_at` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  `recorded_at` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  `recorded_by` BIGINT UNSIGNED NOT NULL DEFAULT 0,
  `recorded_by_role` VARCHAR(20) NOT NULL DEFAULT '',
  `is_backfilled` TINYINT(1) NOT NULL DEFAULT 0,
  `request_uuid` CHAR(36) NOT NULL DEFAULT (UUID()),
  PRIMARY KEY (`lab_report_retraction_id`),
  UNIQUE KEY `uq_lab_report_retraction_1` (`lab_report_id`),
  UNIQUE KEY `uq_lab_report_retraction_request_uuid` (`request_uuid`),
  CONSTRAINT `fk_lab_report_retraction_lab_report` FOREIGN KEY (`lab_report_id`) REFERENCES `lab_report` (`lab_report_id`),
  CONSTRAINT `fk_lab_report_retraction_lab_order` FOREIGN KEY (`correct_lab_order_id`) REFERENCES `lab_order` (`lab_order_id`),
  CONSTRAINT `fk_lab_report_retraction_staff` FOREIGN KEY (`recorded_by`) REFERENCES `staff` (`staff_id`),
  CONSTRAINT `fk_lab_report_retraction_role` FOREIGN KEY (`recorded_by_role`) REFERENCES `role` (`role_code`),
  CONSTRAINT `ck_lab_report_retraction_1` CHECK (`retraction_kind` IN ('wrong_patient','wrong_order','corrupt_file','superseded_by_lab')),
  CONSTRAINT `ck_lab_report_retraction_2` CHECK (`is_backfilled` IN (0,1))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='Wrong-patient/order retraction.';

CREATE TABLE `allergy_confirmation` (
  `allergy_confirmation_id` BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
  `prescription_item_id` BIGINT UNSIGNED NOT NULL,
  `confirmation_type` VARCHAR(24) NOT NULL,
  `displayed_allergies_snapshot` VARCHAR(1000) NOT NULL,
  `was_overridden` TINYINT(1) NOT NULL DEFAULT 0,
  `override_reason` VARCHAR(300) NULL DEFAULT NULL,
  `occurred_at` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  `recorded_at` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  `recorded_by` BIGINT UNSIGNED NOT NULL DEFAULT 0,
  `recorded_by_role` VARCHAR(20) NOT NULL DEFAULT '',
  `is_backfilled` TINYINT(1) NOT NULL DEFAULT 0,
  `request_uuid` CHAR(36) NOT NULL DEFAULT (UUID()),
  PRIMARY KEY (`allergy_confirmation_id`),
  UNIQUE KEY `uq_allergy_confirmation_request_uuid` (`request_uuid`),
  CONSTRAINT `fk_allergy_confirmation_prescription_item` FOREIGN KEY (`prescription_item_id`) REFERENCES `prescription_item` (`prescription_item_id`),
  CONSTRAINT `fk_allergy_confirmation_staff` FOREIGN KEY (`recorded_by`) REFERENCES `staff` (`staff_id`),
  CONSTRAINT `fk_allergy_confirmation_role` FOREIGN KEY (`recorded_by_role`) REFERENCES `role` (`role_code`),
  CONSTRAINT `ck_allergy_confirmation_1` CHECK (`confirmation_type` IN ('free_text_medicine','generic_name_warning')),
  CONSTRAINT `ck_allergy_confirmation_2` CHECK (`was_overridden` IN (0,1)),
  CONSTRAINT `ck_allergy_confirmation_3` CHECK (`is_backfilled` IN (0,1)),
  CONSTRAINT `ck_allergy_confirmation_4` CHECK (was_overridden = 0 OR override_reason IS NOT NULL)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='Snapshot of allergies shown to the doctor (R4.4). Override = safety interrupt.';

CREATE TABLE `lab_report_review` (
  `lab_report_review_id` BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
  `lab_report_id` BIGINT UNSIGNED NOT NULL,
  `review_note` VARCHAR(500) NULL DEFAULT NULL,
  `occurred_at` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  `recorded_at` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  `recorded_by` BIGINT UNSIGNED NOT NULL DEFAULT 0,
  `recorded_by_role` VARCHAR(20) NOT NULL DEFAULT '',
  `is_backfilled` TINYINT(1) NOT NULL DEFAULT 0,
  `request_uuid` CHAR(36) NOT NULL DEFAULT (UUID()),
  PRIMARY KEY (`lab_report_review_id`),
  UNIQUE KEY `uq_lab_report_review_1` (`lab_report_id`),
  UNIQUE KEY `uq_lab_report_review_request_uuid` (`request_uuid`),
  CONSTRAINT `fk_lab_report_review_lab_report` FOREIGN KEY (`lab_report_id`) REFERENCES `lab_report` (`lab_report_id`),
  CONSTRAINT `fk_lab_report_review_staff` FOREIGN KEY (`recorded_by`) REFERENCES `staff` (`staff_id`),
  CONSTRAINT `fk_lab_report_review_role` FOREIGN KEY (`recorded_by_role`) REFERENCES `role` (`role_code`),
  CONSTRAINT `ck_lab_report_review_1` CHECK (`is_backfilled` IN (0,1))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='Doctor reviewed (own event, R7.4).';

CREATE TABLE `refund` (
  `refund_id` BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
  `bill_id` BIGINT UNSIGNED NOT NULL,
  `payment_id` BIGINT UNSIGNED NULL DEFAULT NULL,
  `credit_bill_line_id` BIGINT UNSIGNED NULL DEFAULT NULL,
  `amount` DECIMAL(12,2) NOT NULL,
  `method` VARCHAR(8) NOT NULL,
  `receipt_number` VARCHAR(30) NOT NULL,
  `approval_request_id` BIGINT UNSIGNED NOT NULL,
  `occurred_at` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  `recorded_at` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  `recorded_by` BIGINT UNSIGNED NOT NULL DEFAULT 0,
  `recorded_by_role` VARCHAR(20) NOT NULL DEFAULT '',
  `is_backfilled` TINYINT(1) NOT NULL DEFAULT 0,
  `request_uuid` CHAR(36) NOT NULL DEFAULT (UUID()),
  `corrects_id` BIGINT UNSIGNED NULL DEFAULT NULL,
  PRIMARY KEY (`refund_id`),
  UNIQUE KEY `uq_refund_1` (`receipt_number`),
  UNIQUE KEY `uq_refund_2` (`approval_request_id`),
  UNIQUE KEY `uq_refund_request_uuid` (`request_uuid`),
  CONSTRAINT `fk_refund_bill` FOREIGN KEY (`bill_id`) REFERENCES `bill` (`bill_id`),
  CONSTRAINT `fk_refund_payment` FOREIGN KEY (`payment_id`) REFERENCES `payment` (`payment_id`),
  CONSTRAINT `fk_refund_bill_line` FOREIGN KEY (`credit_bill_line_id`) REFERENCES `bill_line` (`bill_line_id`),
  CONSTRAINT `fk_refund_approval_request` FOREIGN KEY (`approval_request_id`) REFERENCES `approval_request` (`approval_request_id`),
  CONSTRAINT `fk_refund_staff` FOREIGN KEY (`recorded_by`) REFERENCES `staff` (`staff_id`),
  CONSTRAINT `fk_refund_role` FOREIGN KEY (`recorded_by_role`) REFERENCES `role` (`role_code`),
  CONSTRAINT `fk_refund_refund` FOREIGN KEY (`corrects_id`) REFERENCES `refund` (`refund_id`),
  CONSTRAINT `ck_refund_1` CHECK (`method` IN ('cash','upi','card')),
  CONSTRAINT `ck_refund_2` CHECK (`is_backfilled` IN (0,1)),
  CONSTRAINT `ck_refund_3` CHECK (amount > 0)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='Approved refund. Balance = total - payments + refunds.';

CREATE TABLE `dose_administration` (
  `dose_administration_id` BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
  `clinical_order_item_id` BIGINT UNSIGNED NOT NULL,
  `order_item_supply_id` BIGINT UNSIGNED NULL DEFAULT NULL,
  `status` VARCHAR(11) NOT NULL,
  `ordered_dose_value` DECIMAL(10,3) NULL DEFAULT NULL,
  `ordered_dose_unit` VARCHAR(20) NULL DEFAULT NULL,
  `ordered_route` VARCHAR(30) NULL DEFAULT NULL,
  `actual_dose_value` DECIMAL(10,3) NULL DEFAULT NULL,
  `actual_dose_unit` VARCHAR(20) NULL DEFAULT NULL,
  `actual_route` VARCHAR(30) NULL DEFAULT NULL,
  `quantity_consumed` DECIMAL(10,2) NOT NULL DEFAULT 0,
  `deviation_reason` VARCHAR(300) NULL DEFAULT NULL,
  `deviation_authorized_by` BIGINT UNSIGNED NULL DEFAULT NULL,
  `occurred_at` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  `recorded_at` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  `recorded_by` BIGINT UNSIGNED NOT NULL DEFAULT 0,
  `recorded_by_role` VARCHAR(20) NOT NULL DEFAULT '',
  `is_backfilled` TINYINT(1) NOT NULL DEFAULT 0,
  `request_uuid` CHAR(36) NOT NULL DEFAULT (UUID()),
  `corrects_id` BIGINT UNSIGNED NULL DEFAULT NULL,
  PRIMARY KEY (`dose_administration_id`),
  UNIQUE KEY `uq_dose_administration_request_uuid` (`request_uuid`),
  CONSTRAINT `fk_dose_administration_clinical_order_item` FOREIGN KEY (`clinical_order_item_id`) REFERENCES `clinical_order_item` (`clinical_order_item_id`),
  CONSTRAINT `fk_dose_administration_staff` FOREIGN KEY (`deviation_authorized_by`) REFERENCES `staff` (`staff_id`),
  CONSTRAINT `fk_dose_administration_recorded_by` FOREIGN KEY (`recorded_by`) REFERENCES `staff` (`staff_id`),
  CONSTRAINT `fk_dose_administration_role` FOREIGN KEY (`recorded_by_role`) REFERENCES `role` (`role_code`),
  CONSTRAINT `fk_dose_administration_dose_administration` FOREIGN KEY (`corrects_id`) REFERENCES `dose_administration` (`dose_administration_id`),
  CONSTRAINT `fk_dose_administration_order_item_supply_c` FOREIGN KEY (`order_item_supply_id`, `clinical_order_item_id`) REFERENCES `order_item_supply` (`order_item_supply_id`, `clinical_order_item_id`),
  CONSTRAINT `ck_dose_administration_1` CHECK (`status` IN ('given','missed','refused','delayed','stopped')),
  CONSTRAINT `ck_dose_administration_2` CHECK (`is_backfilled` IN (0,1)),
  CONSTRAINT `ck_dose_administration_3` CHECK (quantity_consumed >= 0),
  CONSTRAINT `ck_dose_administration_4` CHECK (quantity_consumed = 0 OR (status = 'given' AND order_item_supply_id IS NOT NULL)),
  CONSTRAINT `ck_dose_administration_5` CHECK (status = 'given' OR deviation_reason IS NOT NULL OR corrects_id IS NOT NULL)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='Nurse records each dose; ordered vs actual stored (R6.1).';

CREATE TABLE `lab_report_critical_mark` (
  `lab_report_critical_mark_id` BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
  `lab_report_id` BIGINT UNSIGNED NOT NULL,
  `mark` VARCHAR(16) NOT NULL,
  `mark_source` VARCHAR(21) NOT NULL,
  `reason` VARCHAR(300) NULL DEFAULT NULL,
  `occurred_at` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  `recorded_at` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  `recorded_by` BIGINT UNSIGNED NOT NULL DEFAULT 0,
  `recorded_by_role` VARCHAR(20) NOT NULL DEFAULT '',
  `is_backfilled` TINYINT(1) NOT NULL DEFAULT 0,
  `request_uuid` CHAR(36) NOT NULL DEFAULT (UUID()),
  PRIMARY KEY (`lab_report_critical_mark_id`),
  UNIQUE KEY `uq_lab_report_critical_mark_request_uuid` (`request_uuid`),
  CONSTRAINT `fk_lab_report_critical_mark_lab_report` FOREIGN KEY (`lab_report_id`) REFERENCES `lab_report` (`lab_report_id`),
  CONSTRAINT `fk_lab_report_critical_mark_staff` FOREIGN KEY (`recorded_by`) REFERENCES `staff` (`staff_id`),
  CONSTRAINT `fk_lab_report_critical_mark_role` FOREIGN KEY (`recorded_by_role`) REFERENCES `role` (`role_code`),
  CONSTRAINT `ck_lab_report_critical_mark_1` CHECK (`mark` IN ('critical','not_critical')),
  CONSTRAINT `ck_lab_report_critical_mark_2` CHECK (`mark_source` IN ('lab_stamp','nurse_observation','doctor_assessment')),
  CONSTRAINT `ck_lab_report_critical_mark_3` CHECK (`is_backfilled` IN (0,1))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='Marks a report critical (R10.2). Latest wins.';

CREATE TABLE `catalog_review_event` (
  `catalog_review_event_id` BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
  `catalog_review_queue_id` BIGINT UNSIGNED NOT NULL,
  `review_action` VARCHAR(20) NOT NULL,
  `resolved_medicine_id` BIGINT UNSIGNED NULL DEFAULT NULL,
  `resolution_note` VARCHAR(300) NULL DEFAULT NULL,
  `occurred_at` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  `recorded_at` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  `recorded_by` BIGINT UNSIGNED NOT NULL DEFAULT 0,
  `recorded_by_role` VARCHAR(20) NOT NULL DEFAULT '',
  `is_backfilled` TINYINT(1) NOT NULL DEFAULT 0,
  `request_uuid` CHAR(36) NOT NULL DEFAULT (UUID()),
  PRIMARY KEY (`catalog_review_event_id`),
  UNIQUE KEY `uq_catalog_review_event_request_uuid` (`request_uuid`),
  CONSTRAINT `fk_catalog_review_event_catalog_review_queue` FOREIGN KEY (`catalog_review_queue_id`) REFERENCES `catalog_review_queue` (`catalog_review_queue_id`),
  CONSTRAINT `fk_catalog_review_event_medicine` FOREIGN KEY (`resolved_medicine_id`) REFERENCES `medicine` (`medicine_id`),
  CONSTRAINT `fk_catalog_review_event_staff` FOREIGN KEY (`recorded_by`) REFERENCES `staff` (`staff_id`),
  CONSTRAINT `fk_catalog_review_event_role` FOREIGN KEY (`recorded_by_role`) REFERENCES `role` (`role_code`),
  CONSTRAINT `ck_catalog_review_event_1` CHECK (`review_action` IN ('mapped','added_to_catalog','rejected')),
  CONSTRAINT `ck_catalog_review_event_2` CHECK (`is_backfilled` IN (0,1))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='Resolution of a queued name. Latest = outcome.';
